SELECT t.path || ' — заморозка объявлена без хэша: держать ей нечего, и это не зелёное' AS detail FROM project_frozen_tree t WHERE t.project_id = $1 AND t.tree_hash = '' UNION ALL SELECT 'заморозка не объявлена ни для одного дерева: стоит ли донор — неизвестно' AS detail WHERE NOT EXISTS (SELECT 1 FROM project_frozen_tree WHERE project_id = $1) UNION ALL SELECT 'датчик заморозки ' || fact_gap($1, 'frozen-tree') || ': стоит ли донор — неизвестно' WHERE EXISTS (SELECT 1 FROM project_frozen_tree WHERE project_id = $1) AND NOT fact_fresh($1, 'frozen-tree') UNION ALL SELECT f.name || '  —  ' || f.detail FROM code_fact f WHERE f.project_id = $1 AND f.kind = 'frozen-tree' AND f.detail NOT LIKE 'стоит на%' ORDER BY 1
